(*----- Function popcount -----*)

Definition popcount_safety_wit_1 :=
forall (v_pre: Z) (PreH1 : (0 <= v_pre)) (PreH2 : (v_pre < 128)),
  ((( &( "c" ) )) # Int  |->_)
  **  ((( &( "v" ) )) # UInt  |-> v_pre)
|--
  “ (0 <= INT_MAX) ”
  &&  “ ((INT_MIN) <= 0) ”
.

Definition popcount_safety_wit_2 :=
(
forall (v_pre: Z) (c: Z) (v: Z) (PreH1 : (0 <= v_pre)) (PreH2 : (v_pre < 128)) (PreH3 : (0 <= v)) (PreH4 : (v < 128)) (PreH5 : (0 <= c)) (PreH6 : (c <= 7)) (PreH7 : (BitCountProgress v_pre v c )) (PreH8 : (v <> 0)),
  ((( &( "v" ) )) # UInt  |-> v)
  **  ((( &( "c" ) )) # Int  |-> c)
|--
  “ ((c + (Z.land v 1) ) <= INT_MAX) ”
  &&  “ ((INT_MIN) <= (c + (Z.land v 1) )) ”
) \/
(
forall (v_pre: Z) (c: Z) (v: Z) (PreH1 : (0 <= v_pre)) (PreH2 : (v_pre < 128)) (PreH3 : (0 <= v)) (PreH4 : (v < 128)) (PreH5 : (0 <= c)) (PreH6 : (c <= 7)) (PreH7 : (BitCountProgress v_pre v c )) (PreH8 : (v <> 0)),
